parser.read(config_path)
print('\nConfiguration sections and key names:')
for section in parser.sections():
    print(f'[{section}]')
    for key in parser[section]:
        print(key)
if parser.defaults():
    print('[DEFAULT]')
    for key in parser.defaults():
        print(key)
